<template><view class="page"><view v-for="item in careers" :key="item.careerId" class="card" @click="open(item)"><text>{{item.careerName}}</text><text v-if="item.viewed">已查看</text></view></view></template>
<script>import{getCatalog,userMessage}from'@/api/zycck';export default{data:()=>({recordId:'',instanceId:'',gameId:'',categoryId:'',careers:[]}),onLoad(o){Object.assign(this,{recordId:o.recordId||'',instanceId:o.instanceId||'',gameId:o.gameId||'',categoryId:o.categoryId||''});this.load()},methods:{async load(){try{const r=await getCatalog({instanceId:this.instanceId,gameId:this.gameId,categoryId:this.categoryId});const d=r.data||{};this.careers=d.careers||d.items||[]}catch(e){uni.showToast({title:userMessage(e,'职业列表加载失败，请重试'),icon:'none'})}},open(i){uni.navigateTo({url:`/pages/zycck/career-detail?recordId=${this.recordId}&instanceId=${this.instanceId}&gameId=${this.gameId}&careerId=${i.careerId}`})}}}</script>
<style scoped>.page{padding:30rpx;background:#f5f7fb;min-height:100vh}.card{display:flex;justify-content:space-between;padding:30rpx;background:#fff;border-radius:16rpx;margin:16rpx 0;color:#243b53}</style>
